class Solution {
    public int calculate(String s) {
        java.util.Deque<Integer> stack = new java.util.ArrayDeque<>();
        int result = 0;
        int num = 0;
        int sign = 1;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (Character.isDigit(c)) {
                num = num * 10 + (c - '0');
            } else if (c == '+') {
                result += sign * num;
                num = 0;
                sign = 1;
            } else if (c == '-') {
                result += sign * num;
                num = 0;
                sign = -1;
            } else if (c == '(') {
                stack.push(result);
                stack.push(sign);
                result = 0;
                sign = 1;
            } else if (c == ')') {
                result += sign * num;
                num = 0;
                result *= stack.pop();
                result += stack.pop();
            }
        }
        return result + sign * num;
    }
}

class Solution {
    private int index;

    public int calculate(String s) {
        index = 0;
        return parse(s);
    }

    private int parse(String s) {
        int result = 0;
        int sign = 1;
        while (index < s.length()) {
            char c = s.charAt(index);
            if (c == ' ') {
                index++;
            } else if (c == '+') {
                sign = 1;
                index++;
            } else if (c == '-') {
                sign = -1;
                index++;
            } else if (c == '(') {
                index++;
                result += sign * parse(s);
            } else if (c == ')') {
                index++;
                return result;
            } else {
                int value = 0;
                while (index < s.length() && Character.isDigit(s.charAt(index))) {
                    value = value * 10 + (s.charAt(index) - '0');
                    index++;
                }
                result += sign * value;
            }
        }
        return result;
    }
}

class Solution {
    public int calculate(String s) {
        java.util.Deque<Integer> nums = new java.util.ArrayDeque<>();
        java.util.Deque<Character> ops = new java.util.ArrayDeque<>();
        boolean expectNumber = true;
        for (int i = 0; i < s.length(); ) {
            char c = s.charAt(i);
            if (c == ' ') {
                i++;
            } else if (Character.isDigit(c)) {
                int value = 0;
                while (i < s.length() && Character.isDigit(s.charAt(i))) {
                    value = value * 10 + (s.charAt(i) - '0');
                    i++;
                }
                nums.push(value);
                expectNumber = false;
            } else if (c == '(') {
                ops.push(c);
                expectNumber = true;
                i++;
            } else if (c == ')') {
                while (!ops.isEmpty() && ops.peek() != '(') {
                    apply(nums, ops);
                }
                ops.pop();
                expectNumber = false;
                i++;
            } else {
                if (expectNumber) {
                    nums.push(0);
                }
                while (!ops.isEmpty() && ops.peek() != '(') {
                    apply(nums, ops);
                }
                ops.push(c);
                expectNumber = true;
                i++;
            }
        }
        while (!ops.isEmpty()) {
            apply(nums, ops);
        }
        return nums.pop();
    }

    private void apply(java.util.Deque<Integer> nums, java.util.Deque<Character> ops) {
        int right = nums.pop();
        int left = nums.pop();
        char op = ops.pop();
        nums.push(op == '+' ? left + right : left - right);
    }
}

