        for (int i = 0; i < s.length(); ) {
            char c = s.charAt(i);
            if (c == ' ') {
                i++;
            } else if (c == '+') {
                sign = signs.peek();
                i++;
            } else if (c == '-') {
                sign = -signs.peek();
                i++;
            } else if (c == '(') {
                signs.push(sign);
                i++;
            } else if (c == ')') {
                signs.pop();
                i++;
            } else {
